            catch (Exception ex)
            {
                Logger.Error(ex, "Error handling save settings click event");
                var box = MessageBoxManager.GetMessageBoxStandard("Error", "Something went wrong", ButtonEnum.Ok);
                await box.ShowAsync();
            }
        }

