            {
                SaveSettings();
                Close();
            }
            catch (Exception ex)
            {
                Logger.Error(ex, "Error handling exit application click event");
                var box = MessageBoxManager.GetMessageBoxStandard("Error", "Something went wrong", ButtonEnum.Ok);
